# 把 HQL「SELECT dept,COUNT(*) FROM emp WHERE salary>5000 GROUP BY dept」
# 转成 MapReduce 实际数据流, 打印每一阶段真实输出
NUM_REDUCERS = 2

def stable_hash(s):
    h = 0
    for c in s:
        h = (31 * h + ord(c)) & 0x7fffffff
    return h

emp = [
    ("eng", 6000), ("eng", 7000), ("sales", 3000), ("sales", 8000),
    ("eng", 9000), ("hr", 4000), ("sales", 2000), ("hr", 5000),
]
# Map 阶段: 过滤 salary>5000 并 emit (dept,1)
map_out = []
for dept, sal in emp:
    if sal > 5000:
        map_out.append((dept, 1))
print("Map 输出(<dept,1>, 已过滤 salary<=5000):")
for r in map_out:
    print("  ", r)
# Shuffle: 按 dept 哈希分区, 相同 dept 进同一 Reducer
buckets = {r: [] for r in range(NUM_REDUCERS)}
for k, v in map_out:
    buckets[stable_hash(k) % NUM_REDUCERS].append((k, v))
print("\nShuffle 分区(按 hash(dept)%2):")
for r in sorted(buckets):
    print(f"  Reducer-{r}: {buckets[r]}")
# Reduce: 同 dept 聚合
result = {}
for r in sorted(buckets):
    for k, v in buckets[r]:
        result[k] = result.get(k, 0) + v
print("\nReduce 聚合结果(同 dept 求和):")
for k in sorted(result):
    print(f"  ({k}, {result[k]})")
print("\n注意: 被过滤掉的 (sales,3000)/(sales,2000)/(hr,4000) 不进 Map 输出 => 谓词下推减少 Shuffle 量")
